IPC_TO_BNS = {item["ipc_section"]: item["bns_section"] for item in SECTION_MAPPINGS}
BNS_TO_IPC = {item["bns_section"]: item["ipc_section"] for item in SECTION_MAPPINGS}


def get_equivalent_section(section: str, act: str):
    section = str(section).strip()
    if act == "IPC":
        return IPC_TO_BNS.get(section)
    return BNS_TO_IPC.get(section)


def get_mappings() -> list[dict]:
    return SECTION_MAPPINGS


def find_mapping_for_query(question: str, legal_era: str) -> dict | None:
    normalized = question.lower()
    for item in SECTION_MAPPINGS:
        section = item["bns_section"] if legal_era == "BNS" else item["ipc_section"]
        title = item["bns_title"] if legal_era == "BNS" else item["ipc_title"]
        other_section = item["ipc_section"] if legal_era == "BNS" else item["bns_section"]
        if section.lower() in normalized or title.lower() in normalized:
            return item
        keywords = set(title.lower().replace(",", "").split())
        if len(keywords & set(normalized.split())) >= 2:
            return item
        if other_section.lower() in normalized:
            return item
    return None
